SELECT base.order_code, details.product_code, details.product_name, details.product_spec, details.product_unit, details.deliver_num, details.delivered_num, details.deliver_time, (CASE WHEN CURRENT_DATE > deliver_time THEN '逾期' ELSE '正常' END) as state FROM oms_order_base as base INNER JOIN oms_order_details as details ON base.order_code = details.order_code AND details.deliver_num > details.delivered_num WHERE base.order_code != #{orderCode} AND details.product_code in
#{item}
ORDER BY base.create_time DESC
